<?php
declare(strict_types=1);require_once __DIR__.'/access.php';require_role('client');$pdo=db();$stmt=$pdo->prepare('SELECT id,name FROM clients WHERE user_id=? AND active=1 LIMIT 1');$stmt->execute([(int)$_SESSION['user']['id']]);$client=$stmt->fetch();$month=preg_match('/^\d{4}-\d{2}$/',(string)($_GET['month']??''))?(string)$_GET['month']:date('Y-m');$start=$month.'-01';$end=date('Y-m-d',strtotime($start.' +1 month'));$message=null;$error=null;
if($_SERVER['REQUEST_METHOD']==='POST'&&$client){verify_csrf();$planId=(int)($_POST['plan_id']??0);$feedback=trim((string)($_POST['message']??''));$check=$pdo->prepare('SELECT id FROM content_plans WHERE id=? AND client_id=?');$check->execute([$planId,$client['id']]);if(!$check->fetchColumn())$error='Plan not found.';elseif($feedback==='')$error='Feedback cannot be empty.';else{$pdo->prepare('INSERT INTO plan_feedback(plan_id,client_id,message) VALUES(?,?,?)')->execute([$planId,$client['id'],$feedback]);$message='Feedback sent to the team.';}}
$plans=[];$feedbackByPlan=[];if($client){$q=$pdo->prepare("SELECT id,title,plan_type,period_start,period_end,COALESCE(planned_date,period_start) planned_date,COALESCE(content_type,'static') content_type,notes,goal,status FROM content_plans WHERE client_id=? AND COALESCE(planned_date,period_start)>=? AND COALESCE(planned_date,period_start)<? ORDER BY planned_date,id");$q->execute([$client['id'],$start,$end]);$plans=$q->fetchAll();$q=$pdo->prepare('SELECT plan_id,message,created_at FROM plan_feedback WHERE client_id=? ORDER BY created_at DESC');$q->execute([$client['id']]);foreach($q->fetchAll() as $row)$feedbackByPlan[$row['plan_id']][]=$row;}
$calendarStart=(new DateTimeImmutable($start))->modify('monday this week');function e(string $v):string{return htmlspecialchars($v,ENT_QUOTES,'UTF-8');}function type_class(string $type):string{return match($type){'reel'=>'reel','carousel'=>'carousel',default=>'static'};}
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>My Plan</title><link rel="stylesheet" href="assets/css/saas.css"><style>.plan-calendar{display:grid;grid-template-columns:repeat(7,minmax(0,1fr));gap:1px;background:#e2e8f0}.plan-day{background:#fff;min-height:125px;padding:8px}.plan-day.muted{background:#f8fafc;color:#94a3b8}.plan-item{display:block;border:0;border-radius:8px;padding:5px 7px;margin-top:5px;font-size:11px;text-align:left;width:100%;cursor:pointer}.plan-item.reel{background:#fef3c7;color:#92400e}.plan-item.static{background:#dcfce7;color:#166534}.plan-item.carousel{background:#e0e7ff;color:#3730a3}.plan-details{padding:10px;border-top:1px solid #e2e8f0;margin-top:8px}.feedback{border-bottom:1px solid #e2e8f0;padding:8px 0}@media(max-width:700px){.plan-day{min-height:90px;padding:5px}.plan-item{font-size:10px;padding:4px}}
</style><script src="assets/js/session-timeout.js" defer></script></head><body class="saas-body"><div class="saas-shell"><aside class="saas-sidebar"><div class="brand"><span>MT</span> Mega Techzy</div><div class="nav-label">Workspace</div><a class="saas-nav" href="client_dashboard.php">▦ <span>Overview</span></a><a class="saas-nav active" href="client_content_plan.php">◷ <span>My Plan</span></a><a class="saas-nav" href="content_archive.php">▤ <span>Archive</span></a><a class="saas-nav" href="view_client_profile.php?client_id=<?= $client?(int)$client['id']:0 ?>">♙ <span>My profile</span></a><a class="saas-nav" href="my_invoices.php">▧ <span>Invoices</span></a><div class="nav-label">Account</div><a class="saas-nav" href="logout.php">↪ <span>Log out</span></a></aside><main class="saas-main"><header class="saas-topbar"><div><h1 class="saas-title">My Content Plan</h1><div class="saas-subtitle">Your monthly plan, read-only with feedback.</div></div></header><?php if($message):?><div class="alert alert-success"><?=e($message)?></div><?php endif;?><?php if($error):?><div class="alert alert-danger"><?=e($error)?></div><?php endif;?><?php if(!$client):?><section class="saas-card"><div class="empty-state">Your login is not linked to a client profile.</div></section><?php else:?><section class="saas-card" style="margin-bottom:16px"><form method="get"><label>Month <input class="form-control" type="month" name="month" value="<?=e($month)?>"></label><button class="btn-indigo">View month</button></form></section><section class="saas-card"><h2><?=e(date('F Y',strtotime($start)))?></h2><div class="plan-calendar"><?php for($i=0;$i<42;$i++):$day=$calendarStart->modify('+'.$i.' days');$dayString=$day->format('Y-m-d');$muted=$day->format('m')!==date('m',strtotime($start));?><div class="plan-day<?=$muted?' muted':''?>"><strong><?=e($day->format('d M'))?></strong><?php foreach($plans as $plan):if($plan['planned_date']===$dayString):?><details><summary class="plan-item <?=type_class($plan['content_type'])?>"><?=e(ucfirst($plan['content_type']))?> · <?=e($plan['title'])?></summary><div class="plan-details"><strong><?=e($plan['title'])?></strong><br>Type: <?=e(ucfirst($plan['content_type']))?><br><?=e($plan['notes']??$plan['goal']??'No notes')?></div></details><?php endif;endforeach;?></div><?php endfor;?></div></section><?php if(!$plans):?><section class="saas-card"><div class="empty-state">No planned posts for this month.</div></section><?php endif;?><?php foreach($plans as $plan):?><section class="saas-card" style="margin-top:16px"><h2><?=e($plan['title'])?></h2><p class="saas-subtitle"><?=e($plan['planned_date'])?> · <?=e(ucfirst($plan['content_type']))?> · <?=e($plan['status'])?></p><p><?=nl2br(e($plan['notes']??$plan['goal']??''))?></p><?php foreach($feedbackByPlan[$plan['id']]??[] as $feedback):?><div class="feedback"><?=nl2br(e($feedback['message']))?><br><small class="saas-subtitle"><?=e($feedback['created_at'])?></small></div><?php endforeach;?><form method="post" style="margin-top:12px"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="plan_id" value="<?=$plan['id']?>"><textarea class="form-control" name="message" rows="2" placeholder="Send feedback to the team"></textarea><button class="btn-outline-indigo" style="margin-top:8px">Send feedback</button></form></section><?php endforeach;?><?php endif;?></main></div></body></html>
